body.script:
(function(){
var NS='http://www.w3.org/1999/xhtml';
function $(id){return document.getElementById(id)}
var body=document.body,search=\( ('search'),count= \)('count'),empty=\( ('empty'),toast= \)('toast');
var settings=\( ('settings'),settingsOpen= \)('settingsOpen'),settingsClose=$('settingsClose');
var groups=[].slice.call(document.querySelectorAll('.group')),lastEsc=0;

function say(m){toast.textContent=m;toast.classList.add('show');clearTimeout(say.t);say.t=setTimeout(function(){toast.classList.remove('show')},1400)}

[].forEach.call(document.querySelectorAll('.acts'),function(box){
var t=box.parentNode.querySelector('.u').textContent;
var b=document.createElementNS(NS,'button');
b.setAttribute('type','button');b.setAttribute('class','btn');b.textContent='copy';
b.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();
try{if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(t).then(function(){b.textContent='copied';b.classList.add('ok');say('copied');setTimeout(function(){b.textContent='copy';b.classList.remove('ok')},1100)})}}catch(err){}});
box.insertBefore(b,box.firstChild);
});

var swatches=[].slice.call(document.querySelectorAll('.sw')),themeLabel=$('themeLabel');
var savedTheme=localStorage.getItem('pi-theme')||'purple';
function setTheme(t){body.setAttribute('data-t',t);swatches.forEach(function(s){s.setAttribute('aria-pressed',String(s.getAttribute('data-s')===t))});if(themeLabel)themeLabel.textContent=t;localStorage.setItem('pi-theme',t)}
setTheme(savedTheme);
swatches.forEach(function(s){s.addEventListener('click',function(){setTheme(s.getAttribute('data-s'))})});

var WALLS=['','https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?w=1920&q=80','https://images.unsplash.com/photo-1522778119026-d647f0596c20?w=1920&q=80','https://images.unsplash.com/photo-1544636331-e26879cd4d9b?w=1920&q=80','https://images.unsplash.com/photo-1503376780353-7e6692767b70?w=1920&q=80'];
function setWall(idx){if(idx<0||idx>=WALLS.length)idx=0;body.style.setProperty('--wall',WALLS[idx]?"url('"+WALLS[idx]+"')":'none');localStorage.setItem('pi-wall',String(idx));[].forEach.call(document.querySelectorAll('.wallbtn'),function(b){b.setAttribute('aria-pressed',String(parseInt(b.getAttribute('data-w'),10)===idx))})}
setWall(parseInt(localStorage.getItem('pi-wall')||'0',10)||0);
[].forEach.call(document.querySelectorAll('.wallbtn'),function(b){b.addEventListener('click',function(){setWall(parseInt(b.getAttribute('data-w'),10))})});

function openAboutBlank(){var win=window.open('about:blank','_blank');if(!win){say('popup blocked');return}try{var doc=win.document;doc.title=document.title;doc.body.style.cssText='margin:0;overflow:hidden;background:#000;height:100vh';var ifr=doc.createElement('iframe');ifr.src=location.href;ifr.style.cssText='position:fixed;inset:0;width:100%;height:100%;border:0;background:#000';doc.body.appendChild(ifr);say('opened in about:blank')}catch(e){try{win.location=location.href}catch(e2){}}}
var aboutBlankBtn=$('aboutBlankBtn');if(aboutBlankBtn)aboutBlankBtn.addEventListener('click',function(e){e.preventDefault();openAboutBlank()});

var autoCloakBtn=$('autoCloakBtn'),autoCloak=localStorage.getItem('pi-autocloak')==='1';
function applyAutoCloak(){if(autoCloakBtn)autoCloakBtn.setAttribute('aria-checked',String(autoCloak));localStorage.setItem('pi-autocloak',autoCloak?'1':'0')}
applyAutoCloak();
if(autoCloakBtn)autoCloakBtn.addEventListener('click',function(){autoCloak=!autoCloak;applyAutoCloak();if(autoCloak){openAboutBlank();setTimeout(function(){location.replace('https://classroom.google.com/')},400)}});
if(autoCloak&&!sessionStorage.getItem('pi-cloaked')){sessionStorage.setItem('pi-cloaked','1');openAboutBlank();setTimeout(function(){location.replace('https://classroom.google.com/')},500)}

var cloaks={classroom:{title:'Classes',favicon:'https://ssl.gstatic.com/classroom/favicon.png'},drive:{title:'My Drive - Google Drive',favicon:'https://ssl.gstatic.com/docs/doclist/images/drive_2022q3_32dp.png'},docs:{title:'Google Docs',favicon:'https://ssl.gstatic.com/docs/documents/images/kix-favicon7.ico'},google:{title:'Google',favicon:'https://www.google.com/favicon.ico'},blank:{title:'',favicon:''},reset:{title:'Proxy Index',favicon:''}};
[].forEach.call(document.querySelectorAll('.cloak-btn'),function(btn){btn.addEventListener('click',function(){var key=btn.getAttribute('data-cloak'),c=cloaks[key];if(!c)return;document.title=c.title;var link=document.querySelector("link[rel*='icon']")||document.createElement('link');link.rel='icon';link.href=c.favicon||'data:,';document.head.appendChild(link);[].forEach.call(document.querySelectorAll('.cloak-btn'),function(b){b.classList.remove('active')});btn.classList.add('active');say('tab cloaked: '+(c.title||'blank'))})});

var snowBtn=\( ('snowBtn'),snowFx= \)('snowFx'),snowOn=localStorage.getItem('pi-snow')==='1';
function buildSnow(){if(!snowFx)return;snowFx.innerHTML='';for(var i=0;i<55;i++){var p=document.createElementNS(NS,'i'),left=Math.random()*100,dur=6+Math.random()*10,delay=-Math.random()*dur,dx=(Math.random()*40-20),size=3+Math.random()*4;p.setAttribute('style','left:'+left+'%;width:'+size+'px;height:'+size+'px;--dx:'+dx+'px;animation-duration:'+dur+'s;animation-delay:'+delay+'s');snowFx.appendChild(p)}}
function applySnow(){body.setAttribute('data-snow',snowOn?'1':'0');if(snowBtn)snowBtn.setAttribute('aria-checked',String(snowOn));localStorage.setItem('pi-snow',snowOn?'1':'0');if(snowOn)buildSnow()}
applySnow();if(snowBtn)snowBtn.addEventListener('click',function(){snowOn=!snowOn;applySnow()});

var glitchBtn=$('glitchBtn'),glitchOn=localStorage.getItem('pi-glitch')==='1';
function applyGlitch(){body.setAttribute('data-glitch',glitchOn?'1':'0');if(glitchBtn)glitchBtn.setAttribute('aria-checked',String(glitchOn));localStorage.setItem('pi-glitch',glitchOn?'1':'0')}
applyGlitch();if(glitchBtn)glitchBtn.addEventListener('click',function(){glitchOn=!glitchOn;applyGlitch()});

var wallMove=$('wallMove'),moveOn=localStorage.getItem('pi-move')!=='0';
function applyMove(){body.setAttribute('data-move',moveOn?'1':'0');if(wallMove)wallMove.setAttribute('aria-checked',String(moveOn));localStorage.setItem('pi-move',moveOn?'1':'0')}
applyMove();if(wallMove)wallMove.addEventListener('click',function(){moveOn=!moveOn;applyMove()});

function update(){var q=(search.value||'').trim().toLowerCase(),g=0,l=0;groups.forEach(function(grp){var hitName=!q||grp.querySelector('.gn').textContent.toLowerCase().indexOf(q)>-1,n=0;[].forEach.call(grp.querySelectorAll('.li'),function(it){var hit=hitName||it.querySelector('.u').textContent.toLowerCase().indexOf(q)>-1;it.classList.toggle('hidden',!hit);if(hit)n++});var pill=grp.querySelector('.pill');if(pill)pill.textContent=n;grp.classList.toggle('hidden',!n);if(q&&n)grp.open=true;if(n){g++;l+=n}});if(count)count.innerHTML='<b>'+g+'</b> groups, <b>'+l+'</b> links';if(empty)empty.classList.toggle('show',!g)}
if(search)search.addEventListener('input',update);

document.addEventListener('keydown',function(e){if(e.key==='/'&&document.activeElement!==search){e.preventDefault();search.focus();search.select()}if(e.key==='Escape'){var now=Date.now();if(now-lastEsc<400)location.replace('https://classroom.google.com/');lastEsc=now;settings.classList.remove('open');if(search.value){search.value='';update()}}});
if(settingsOpen)settingsOpen.addEventListener('click',function(){settings.classList.toggle('open')});
if(settingsClose)settingsClose.addEventListener('click',function(){settings.classList.remove('open')});
buildSnow();
})();
